def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full, uniformly colored rows and columns are the compartment dividers.
    hdivs = [r for r, row in enumerate(grid)
             if row[0] != 0 and all(v == row[0] for v in row)]
    vdivs = [c for c in range(w)
             if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    sep = grid[hdivs[0]][0]

    def intervals(size, divs):
        bounds = [-1] + divs + [size]
        return [(bounds[i] + 1, bounds[i + 1])
                for i in range(len(bounds) - 1)]

    row_cells = intervals(h, hdivs)
    col_cells = intervals(w, vdivs)

    # The first cell of each band contains that band's color marker.
    labels = []
    for r0, r1 in row_cells:
        counts = {}
        for r in range(r0, r1):
            for c in range(col_cells[0][0], col_cells[0][1]):
                color = grid[r][c]
                if color not in (0, sep):
                    counts[color] = counts.get(color, 0) + 1
        labels.append(max(counts, key=counts.get))

    label_set = set(labels)

    # Find the non-marker colored pattern and record its coordinates in its cell.
    pattern_color = None
    pattern_count = -1
    for color in range(1, 10):
        if color == sep or color in label_set:
            continue
        count = sum(grid[r][c] == color
                    for r in range(h) for c in range(w))
        if count > pattern_count:
            pattern_color, pattern_count = color, count

    pattern = []
    for r0, r1 in row_cells:
        for c0, c1 in col_cells:
            coords = [(r - r0, c - c0)
                      for r in range(r0, r1)
                      for c in range(c0, c1)
                      if grid[r][c] == pattern_color]
            if coords:
                pattern = coords
                break
        if pattern:
            break

    out = [[0] * w for _ in range(h)]
    for r in hdivs:
        for c in range(w):
            out[r][c] = sep
    for c in vdivs:
        for r in range(h):
            out[r][c] = sep

    for band, (r0, r1) in enumerate(row_cells):
        for c0, c1 in col_cells:
            for dr, dc in pattern:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = labels[band]

    return out
